SELECT ST_Area_Spheroid(ST_Union_Agg(geometry)) / 1e6 AS total_area_sqkm
FROM countries
WHERE continent = 'Africa';

SELECT continent, ST_AsGeoJSON(ST_Centroid(ST_Union_Agg(geometry))) AS center_geojson
FROM countries
GROUP BY continent;

WITH brazil AS (
  SELECT geometry AS geom FROM countries WHERE name = 'Brazil'
),
brazil_cities AS (
  SELECT geometry AS geom FROM populated_places
  WHERE country = 'Brazil' AND pop_max > 100000
),
collected AS (
  SELECT ST_Collect(list(geom)) AS geom FROM brazil_cities
),
hull AS (
  SELECT ST_ConvexHull(geom) AS geom FROM collected
),
outside AS (
  SELECT ST_Difference(h.geom, b.geom) AS geom
  FROM hull h, brazil b
)
SELECT ST_Area_Spheroid(geom) / 1e6 AS area_sqkm
FROM outside
WHERE geom IS NOT NULL AND NOT ST_IsEmpty(geom);
